 static string ResolvePortable(string chosen){var root=Path.GetFullPath(chosen);if(Path.GetFileName(root).Equals("Library",StringComparison.OrdinalIgnoreCase)&&File.Exists(Path.Combine(Path.GetDirectoryName(root)!,"manifest.json")))root=Path.GetDirectoryName(root)!;foreach(var relative in new[]{"","PRIVATE-DATA/PORTABLE-APPROVED-LIBRARY","PORTABLE-APPROVED-LIBRARY","WINDOWS-CODEX-HANDOFF/PRIVATE-DATA/PORTABLE-APPROVED-LIBRARY"}){var candidate=Path.Combine(root,relative);if(File.Exists(Path.Combine(candidate,"manifest.json"))&&File.Exists(Path.Combine(candidate,"Library/index.json")))return candidate;}throw new InvalidDataException("اختر مجلد PORTABLE-APPROVED-LIBRARY أو مجلد الحزمة الذي يحتوي PRIVATE-DATA؛ لم تُغيّر أي بيانات.");}
